// ✅ PROCESAMIENTO DE ACCIONES DE USUARIO
const received = $json;

// Información detallada de la acción capturada
const actionInfo = {
  // Datos principales de la acción
  actionType: received.action || received.type || 'unknown',
  element: received.element || 'elemento no especificado',
  value: received.value || '',

  // Contexto de la página
  pageUrl: received.url || window.location?.href || 'URL no disponible',
  pageTitle: received.title || 'Título no disponible',

  // Información de sesión
  sessionId: received.sessionId || `session_${Date.now()}`,
  timestamp: received.timestamp || new Date().toISOString(),

  // Metadatos técnicos
  userAgent: received.userAgent || 'No disponible',
  selector: received.selector || '',
  coordinates: received.coordinates || null
};

// Crear respuesta detallada con información visible
const detailedResponse = {
  success: true,
  message: `🎯 PASO CAPTURADO: ${actionInfo.actionType.toUpperCase()}`,

  // Información del paso capturado
  stepDetails: {
    action: actionInfo.actionType,
    target: actionInfo.element,
    value: actionInfo.value,
    page: actionInfo.pageTitle,
    url: actionInfo.pageUrl,
    when: actionInfo.timestamp
  },

  // Información de la sesión
  sessionInfo: {
    sessionId: actionInfo.sessionId,
    stepNumber: 1, // Se incrementará en versiones futuras
    totalSteps: 1  // Se actualizará dinámicamente
  },

  // Estado del workflow
  status: {
    captured: true,
    stored: true,
    readyForNextStep: true,
    message: 'Continúe con más acciones o genere tests'
  },

  // Log para debugging
  debug: {
    receivedData: received,
    processedAt: new Date().toISOString(),
    nodeId: 'capture-webhook'
  }
};

// Console log detallado para monitoreo
console.log('🚀 ACCIÓN PROCESADA:', {
  tipo: actionInfo.actionType,
  elemento: actionInfo.element,
  página: actionInfo.pageTitle,
  sesión: actionInfo.sessionId,
  timestamp: actionInfo.timestamp
});

// Retornar respuesta estructurada
return [{json: detailedResponse}];
